#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────
#
# chas-claimer: first deployment to Cloudflare Pages, D1 and Access.
#
#   bash scripts/setup-wizard.sh
#
# Run it from a clone of github.com/jurasolutions/chas-claimer on Ting Yu's own machine. The plan
# behind each stage is .scratch/chas-claimer/reviews/infra.md and the README's "Deploy" section.
#
# What it never does: print a secret, write a secret to a file in the repo, or change anything at
# Cloudflare without asking first. The values it remembers between runs (database IDs, the Access
# team domain and AUD tag, hostnames) are not secrets. They go to .wrangler/setup-wizard.env, which
# git ignores. Generated keys go to your clipboard only, and the clipboard is cleared afterwards.

WRANGLER_VERSION="4.86.0"
COMPATIBILITY_DATE="2026-05-01"
D1_PRODUCTION="chas-claimer"
D1_PREVIEW="chas-claimer-preview"

# wr runs the pinned wrangler (the last release that runs on Node 20, as package.json uses).
wr() { npx --yes "wrangler@${WRANGLER_VERSION}" "$@"; }

# run_confirmed "what it does" cmd... shows a command that changes something, and runs it on yes.
run_confirmed() {
  local what="$1"; shift
  say "$what"
  note "  \$ $*"
  if confirm "Run it now?"; then
    "$@"
  else
    SKIPPED+=("$what")
    warn "skipped. Run it yourself later."
  fi
}

# to_clipboard copies stdin to the clipboard, or fails when there is no clipboard tool.
to_clipboard() {
  if   command -v pbcopy   >/dev/null 2>&1; then pbcopy
  elif command -v clip.exe >/dev/null 2>&1; then clip.exe
  elif command -v wl-copy  >/dev/null 2>&1; then wl-copy
  elif command -v xclip    >/dev/null 2>&1; then xclip -selection clipboard
  else return 1; fi
}
clear_clipboard() { printf '' | to_clipboard >/dev/null 2>&1 || true; }

# new_secret "LABEL" makes 32 random bytes (base64) and puts them on the clipboard without showing
# them. With no clipboard tool, the value goes to a private temporary file that is deleted after.
new_secret() {
  local label="$1" value file=""
  value=$(openssl rand -base64 32)
  if printf '%s' "$value" | to_clipboard >/dev/null 2>&1; then
    say "A new ${label} is on your clipboard. It is not shown here."
  else
    file=$(mktemp)
    chmod 600 "$file"
    printf '%s\n' "$value" > "$file"
    warn "No clipboard tool found. The value is in $file, readable only by you."
    warn "That file is deleted when you press Enter."
  fi
  value=""
  step "Paste it into your password manager first, as \"chas-claimer ${label}\"."
  step "Then paste it into the Pages dashboard, as described above."
  pause "Saved in both places? Press Enter to clear it"
  clear_clipboard
  [[ -n "$file" ]] && rm -f "$file"
  return 0
}

# d1_id NAME prints a D1 database's ID from `wrangler d1 list --json`, or nothing.
d1_id() {
  wr d1 list --json 2>/dev/null | node -e '
    let s = ""; process.stdin.on("data", (d) => (s += d)).on("end", () => {
      try { const db = JSON.parse(s).find((d) => d.name === process.argv[1]); process.stdout.write(db ? String(db.uuid) : ""); }
      catch { /* not JSON: the caller asks instead */ }
    });' "$1" || true
}

# expect_access_redirect HOST checks that an anonymous request is sent to the Access login.
expect_access_redirect() {
  local host="$1" result code location
  result=$(curl -sS -o /dev/null --max-time 20 -w '%{http_code} %{redirect_url}' "https://${host}/" 2>/dev/null || echo "000 ")
  code="${result%% *}"; location="${result#* }"
  if [[ "$code" =~ ^30[1278]$ && "$location" == *cloudflareaccess.com* ]]; then
    printf '  %s✓%s %s sends anonymous visitors to the Access login (%s)\n' "$GREEN" "$RESET" "$host" "$code"
  else
    warn "${host} answered ${code} without a redirect to Access. Stop here: the desk is not behind Access on this hostname."
    SKIPPED+=("Put ${host} inside the Access application, then run the smoke check again")
  fi
}

run_wizard() {

cd "$(dirname "${BASH_SOURCE[0]}")/.."
REPO_ROOT="$(pwd)"
mkdir -p .wrangler
ENV_FILE=".wrangler/setup-wizard.env"

TOTAL_STAGES=14

banner "chas-claimer: deploy the claims desk"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Before you start"
say "This sets up the desk on Cloudflare: two D1 databases, a Pages project, one Access"
say "application and a service token for the clinic's connector. Allow about 45 minutes."
say ""
say "Have these ready:"
step "A Cloudflare account for Jura Solutions, signed in at dash.cloudflare.com."
step "Cloudflare Zero Trust turned on for that account, with a team name chosen."
step "A password manager entry ready for chas-claimer. Generated keys go there first."
step "The reviewer and officer email addresses."
step "The desk's custom domain, if one is decided. It can be added later."
say ""
note "Recommended: the Workers Paid plan. On the free plan a Function gets 10 ms of CPU per"
note "request, which a 100-visit import can exceed, and D1 Time Travel keeps 7 days, not 30."
note "Rotating IDENTIFIER_KEY moves 150 visit revisions per request, which assumes Workers Paid."
say ""
say "Checking the tools this wizard uses (read-only):"
for tool in node npx openssl curl git; do
  if command -v "$tool" >/dev/null 2>&1; then
    printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$tool"
  else
    warn "$tool is missing. Install it, then run this wizard again."
    exit 1
  fi
done
node_major="$(node -p 'process.versions.node.split(".")[0]')"
if [[ "$node_major" != "20" ]]; then
  warn "Node ${node_major} found. The repo is verified on Node 20 (see .nvmrc); wrangler ${WRANGLER_VERSION} needs it."
fi
pause "Ready? Press Enter"

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Sign wrangler in to Cloudflare"
say "Checking who wrangler is signed in as (read-only):"
whoami_out="$(wr whoami 2>&1 || true)"
printf '%s\n' "$whoami_out" | sed 's/^/    /' | tail -n 15
if grep -qi "not authenticated" <<<"$whoami_out"; then
  run_confirmed "Sign in through the browser (wrangler login stores an OAuth token on this machine)." wr login
else
  say "Check that the account above is Jura Solutions' account. If not, run: npx wrangler@${WRANGLER_VERSION} logout"
fi
pause

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Create the two D1 databases"
say "Production data goes in ${D1_PRODUCTION}. Preview deployments get their own ${D1_PREVIEW},"
say "so code on a branch never touches the clinic's records."
note "--location apac asks Cloudflare to place the database's primary copy in Asia-Pacific. It is a"
note "hint, not a guarantee of Singapore, and it cannot be changed after creation."
say ""
for name in "$D1_PRODUCTION" "$D1_PREVIEW"; do
  existing="$(d1_id "$name")"
  if [[ -n "$existing" ]]; then
    printf '  %s✓%s %s already exists\n' "$GREEN" "$RESET" "$name"
  else
    run_confirmed "Create ${name} in Asia-Pacific." wr d1 create "$name" --location apac
  fi
done
D1_PRODUCTION_ID="$(d1_id "$D1_PRODUCTION")"
D1_PREVIEW_ID="$(d1_id "$D1_PREVIEW")"
[[ -n "$D1_PRODUCTION_ID" ]] || ask D1_PRODUCTION_ID "The ${D1_PRODUCTION} database_id (from the output above):"
[[ -n "$D1_PREVIEW_ID" ]] || ask D1_PREVIEW_ID "The ${D1_PREVIEW} database_id (from the output above):"
write_env D1_PRODUCTION_ID "$D1_PRODUCTION_ID"
write_env D1_PREVIEW_ID "$D1_PREVIEW_ID"
pause

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Apply the schema to both databases"
say "There is no wrangler.toml in this repo (Pages would take its bindings from it), so the"
say "migration commands use a config written to .wrangler/d1-remote.toml, which git ignores."
D1_CONFIG=".wrangler/d1-remote.toml"
cat > "$D1_CONFIG" <<TOML
# Written by scripts/setup-wizard.sh for wrangler d1 migrations only. Git ignores it and Pages never
# reads it. The production bindings live in the Pages dashboard.
name = "chas-claimer-migrations"
compatibility_date = "${COMPATIBILITY_DATE}"

[[d1_databases]]
binding = "DB"
database_name = "${D1_PRODUCTION}"
database_id = "${D1_PRODUCTION_ID}"
migrations_dir = "${REPO_ROOT}/migrations"

[[d1_databases]]
binding = "DB_PREVIEW"
database_name = "${D1_PREVIEW}"
database_id = "${D1_PREVIEW_ID}"
migrations_dir = "${REPO_ROOT}/migrations"
TOML
printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$D1_CONFIG"
for name in "$D1_PRODUCTION" "$D1_PREVIEW"; do
  say ""
  say "Migrations not yet applied to ${name} (read-only):"
  wr d1 migrations list "$name" --remote -c "$D1_CONFIG" 2>&1 | tail -n 8 | sed 's/^/    /' || true
  run_confirmed "Apply them to ${name}." wr d1 migrations apply "$name" --remote -c "$D1_CONFIG"
done
pause

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Create the Pages project"
open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages"
step "Create, then the Pages tab, then Connect to Git (or Import an existing Git repository)."
step "Pick jurasolutions/chas-claimer. Grant the GitHub app access to that repo only."
step "Project name: chas-claimer. Production branch: main. Framework preset: None."
step "Build command: npm run build. Build output directory: dist. Root directory: blank."
step "Save and Deploy."
say ""
note "The first deployment is safe to let run: with no Access settings, no key and an empty"
note "database, every API route answers 503 and there is no data to show. The build picks up"
note "Node 20 from .nvmrc."
ask PAGES_PROJECT "The project name you chose [chas-claimer]:"
PAGES_PROJECT="${PAGES_PROJECT:-chas-claimer}"
write_env PAGES_PROJECT "$PAGES_PROJECT"
say ""
say "Pages projects on this account (read-only):"
wr pages project list 2>&1 | tail -n 10 | sed 's/^/    /' || true
pause

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Create the one Access application"
say "One application must cover every address the desk answers on. Its AUD tag is the one value"
say "the desk checks, so a second application (with a second AUD) would lock users out."
open_url "https://one.dash.cloudflare.com/"
step "Access, then Applications, then Add an application, then Self-hosted."
step "Name: chas-claimer desk. Session duration: 8 hours."
step "Add these public hostnames, each as its own destination:"
note "      ${PAGES_PROJECT}.pages.dev"
note "      *.${PAGES_PROJECT}.pages.dev        (every preview deployment)"
note "      the custom domain, once there is one (stage 11)"
step "Policy \"Desk staff\": action Allow, include Emails, listing every reviewer and officer."
step "Login method: One-time PIN, or the identity provider Jura uses."
step "Save. Then open the application's Overview (or Basic information) and find the AUD tag."
warn "Do not turn on the Access toggle in the Pages project's own settings: it makes a second"
warn "application with a different AUD, and previews would refuse every sign-in."
ask ACCESS_TEAM_DOMAIN "Your team domain, like <team>.cloudflareaccess.com (no https://):"
ACCESS_TEAM_DOMAIN="${ACCESS_TEAM_DOMAIN#https://}"; ACCESS_TEAM_DOMAIN="${ACCESS_TEAM_DOMAIN%/}"
write_env ACCESS_TEAM_DOMAIN "$ACCESS_TEAM_DOMAIN"
ask ACCESS_AUD "The application's AUD tag (not a secret):"
write_env ACCESS_AUD "$ACCESS_AUD"
pause

# ── 7 ────────────────────────────────────────────────────────────────────
stage "Create the connector's service token"
say "The clinic's connector passes Access with this token, then shows the desk CONNECTOR_TOKEN."
say "Two independent secrets stand between the internet and the import route."
open_url "https://one.dash.cloudflare.com/"
step "Access, then Service credentials (or Service auth), then Service Tokens, then Create."
step "Name: chas-claimer-connector. Duration: 1 year."
step "Copy the Client ID and Client Secret straight into the password manager. The secret is"
step "shown once. This wizard does not ask for them."
step "Back on the chas-claimer desk application, add a policy \"Connector\": action Service Auth,"
step "include Service Token chas-claimer-connector."
ask SERVICE_TOKEN_EXPIRES "The token's expiry date, YYYY-MM-DD, for a renewal reminder:"
write_env SERVICE_TOKEN_EXPIRES "$SERVICE_TOKEN_EXPIRES"
note "Put a reminder in your calendar a month before ${SERVICE_TOKEN_EXPIRES}. An expired token stops"
note "every import until the clinic's connector has the new one."
pause

# ── 8 ────────────────────────────────────────────────────────────────────
stage "Runtime and the D1 bindings"
open_url "https://dash.cloudflare.com/?to=/:account/pages/view/${PAGES_PROJECT}/settings"
note "If the link lands elsewhere, open Workers & Pages, then ${PAGES_PROJECT}, then Settings."
step "Runtime: compatibility date ${COMPATIBILITY_DATE}. No compatibility flags."
step "Bindings, Production: add a D1 database binding, variable name DB, database ${D1_PRODUCTION}."
step "Bindings, Preview: add a D1 database binding, variable name DB, database ${D1_PREVIEW}."
step "Build: check the command is npm run build and the output directory is dist."
warn "Never bind ${D1_PRODUCTION} to Preview. Any pushed branch would then run against the clinic's data."
pause

# ── 9 ────────────────────────────────────────────────────────────────────
stage "Plain-text variables"
say "Settings, Variables and Secrets. Add each as type Text, in the environment shown."
say ""
say "Both Production and Preview:"
note "  ACCESS_TEAM_DOMAIN = ${ACCESS_TEAM_DOMAIN}"
note "  ACCESS_AUD         = ${ACCESS_AUD}"
note "  ROLE_REVIEWERS     = reviewer emails, comma-separated"
note "  ROLE_OFFICERS      = officer emails, comma-separated"
say "Production only:"
note "  AI_DAILY_CALL_CAP  = 200, or leave unset for the default of 200"
say "Preview only:"
note "  DEMO_MODE          = yes   (synthetic clinic import and the payer simulator)"
note "  AI_DAILY_CALL_CAP  = 20"
say ""
say "Leave these unset everywhere:"
note "  ALLOW_REAL_IDENTIFIERS  until the data-intermediary agreement is signed (then Production only)"
note "  DEMO_MODE on Production, ANTHROPIC_BASE_URL, and DEV_USER (it only works on localhost)"
pause

# ── 10 ───────────────────────────────────────────────────────────────────
stage "Secrets"
say "Settings, Variables and Secrets. Add each as type Secret. Pages never shows a secret again,"
say "so the password manager copy is the only one. Losing IDENTIFIER_KEY loses every sealed identity."
say ""
say "1 of 3: IDENTIFIER_KEY for Production."
new_secret "IDENTIFIER_KEY (production)"
say ""
say "2 of 3: IDENTIFIER_KEY for Preview. A different key, so preview data can never be opened with"
say "the production key or the other way round."
new_secret "IDENTIFIER_KEY (preview)"
say ""
say "3 of 3: CONNECTOR_TOKEN for Production only. The clinic's connector gets the same value later."
note "Preview gets no CONNECTOR_TOKEN, so no connector can import into a preview."
new_secret "CONNECTOR_TOKEN (production)"
say ""
say "Optional now, needed for AI suggestions: ANTHROPIC_API_KEY, from Jura's own Anthropic account."
if confirm "Set up the Anthropic key now?"; then
  open_url "https://console.anthropic.com/settings/keys"
  step "Create a key named chas-claimer. Set a monthly spend limit on its workspace."
  step "Copy it into the password manager, then into Pages as a Secret on Production."
  pause "Done? Press Enter"
else
  SKIPPED+=("ANTHROPIC_API_KEY: optional. The desk works without AI until it is set")
fi
note "Payer API tokens (PAYER_<ID>_API_TOKEN) come later, one per payer moved to the api channel."
pause

# ── 11 ───────────────────────────────────────────────────────────────────
stage "Custom domain (optional)"
say "Skip this if the desk's domain isn't decided. The pages.dev address works behind Access meanwhile."
ask CUSTOM_DOMAIN "The desk's custom domain, like claims.example.sg (Enter to skip):" || CUSTOM_DOMAIN=""
if [[ -n "${CUSTOM_DOMAIN:-}" ]]; then
  write_env CUSTOM_DOMAIN "$CUSTOM_DOMAIN"
  step "First, add ${CUSTOM_DOMAIN} as a destination on the chas-claimer desk Access application."
  open_url "https://dash.cloudflare.com/?to=/:account/pages/view/${PAGES_PROJECT}/domains"
  step "Then, in the Pages project: Custom domains, Set up a custom domain, ${CUSTOM_DOMAIN}."
  step "Follow the DNS step it shows. Wait until the domain shows Active."
  warn "Access first, domain second. The other way round leaves a window with no sign-in."
  pause
else
  SKIPPED+=("Custom domain: add it to the Access application first, then to Pages")
fi

# ── 12 ───────────────────────────────────────────────────────────────────
stage "Redeploy so the settings take effect"
say "Pages binds variables and bindings when a deployment is created. The first deployment"
say "predates them, so it still answers 503 until you redeploy."
open_url "https://dash.cloudflare.com/?to=/:account/pages/view/${PAGES_PROJECT}"
step "Deployments, the latest Production deployment, then Retry deployment."
step "Wait for it to show Success."
say ""
say "Recent deployments (read-only):"
wr pages deployment list --project-name "$PAGES_PROJECT" 2>&1 | tail -n 8 | sed 's/^/    /' || true
pause

# ── 13 ───────────────────────────────────────────────────────────────────
stage "Smoke check"
PRIMARY_HOST="${CUSTOM_DOMAIN:-${PAGES_PROJECT}.pages.dev}"
say "Every request here is a read, or a POST the desk refuses before it reads anything."
say ""
say "Anonymous visitors must be sent to the Access login on every hostname:"
expect_access_redirect "${PAGES_PROJECT}.pages.dev"
expect_access_redirect "access-check.${PAGES_PROJECT}.pages.dev"
[[ -n "${CUSTOM_DOMAIN:-}" ]] && expect_access_redirect "$CUSTOM_DOMAIN"
say ""
say "Now through Access with the connector's service token. Paste it; it is not shown or saved."
CF_ID=""; CF_SECRET=""
ask_secret CF_ID "Service token Client ID:"
ask_secret CF_SECRET "Service token Client Secret:"
hdr="$(mktemp)"; body="$(mktemp)"
chmod 600 "$hdr" "$body"
trap 'rm -f "$hdr" "$body"' EXIT
printf 'CF-Access-Client-Id: %s\nCF-Access-Client-Secret: %s\n' "$CF_ID" "$CF_SECRET" > "$hdr"
CF_ID=""; CF_SECRET=""

code="$(curl -sS -H @"$hdr" -o "$body" --max-time 20 -w '%{http_code}' "https://${PRIMARY_HOST}/api/me" || echo 000)"
case "$code" in
  401|403) printf '  %s✓%s /api/me answered %s: Access let the token through and the desk checked it\n' "$GREEN" "$RESET" "$code" ;;
  503) warn "/api/me answered 503 $(head -c 120 "$body"): ACCESS_TEAM_DOMAIN or ACCESS_AUD is not on this deployment. Redeploy (stage 12)." ;;
  *) warn "/api/me answered ${code}. Expected 401. A login page means the Service Auth policy is missing (stage 7)." ;;
esac

code="$(curl -sS -H @"$hdr" -o "$body" --max-time 20 -w '%{http_code}' -X POST \
  -H 'Content-Type: application/json' -H 'Authorization: Bearer smoke-check-not-the-connector-token' \
  --data '{}' "https://${PRIMARY_HOST}/api/imports" || echo 000)"
case "$code" in
  401) printf '  %s✓%s POST /api/imports refused a wrong connector token (401)\n' "$GREEN" "$RESET" ;;
  503) warn "POST /api/imports answered 503: CONNECTOR_TOKEN is missing or shorter than 43 characters on Production." ;;
  *) warn "POST /api/imports answered ${code}. Expected 401." ;;
esac

page_headers="$(curl -sS -H @"$hdr" -o /dev/null -D - --max-time 20 "https://${PRIMARY_HOST}/" 2>/dev/null || true)"
if grep -qi '^content-security-policy:.*frame-ancestors' <<<"$page_headers"; then
  printf '  %s✓%s the page carries the Content Security Policy from public/_headers\n' "$GREEN" "$RESET"
else
  warn "The page has no Content Security Policy. Check that dist/_headers was deployed."
fi
rm -f "$hdr" "$body"
say ""
say "Last, as a person:"
open_url "https://${PRIMARY_HOST}/api/me"
step "Sign in with a reviewer's email. The page shows that email with roles reviewer and officer."
step "Open https://${PRIMARY_HOST}/ and check the desk loads and shows no 'not configured' message."
step "On a preview deployment (DEMO_MODE=yes), run the synthetic clinic import. It proves the"
step "preview IDENTIFIER_KEY and database work end to end."
if ! confirm "Did /api/me show your email with the reviewer role?"; then
  SKIPPED+=("Sign-in check: compare ROLE_REVIEWERS with the email you signed in with, then redeploy")
fi

# ── 14 ───────────────────────────────────────────────────────────────────
stage "Backups and hand-off"
say "D1 Time Travel is always on. Today's restore point for ${D1_PRODUCTION} (read-only):"
wr d1 time-travel info "$D1_PRODUCTION" 2>&1 | tail -n 6 | sed 's/^/    /' || true
say ""
say "Keep a note of how to restore and how to roll back. Both are in the README, \"Deploy\"."
say ""
say "For the clinic's connector machine, set these in its environment (never in a file in the repo):"
note "  CLAIMS_DESK_URL          https://${PRIMARY_HOST}"
note "  CONNECTOR_TOKEN          from the password manager (stage 10)"
note "  CF_ACCESS_CLIENT_ID      from the password manager (stage 7)"
note "  CF_ACCESS_CLIENT_SECRET  from the password manager (stage 7)"
note "Then: npm run connector -- dry-run ..., and push only once the dry run reads cleanly."
warn "Real patient data waits for the data-intermediary agreement and ALLOW_REAL_IDENTIFIERS=yes."
pause "Press Enter to finish"

finish
}

run_wizard "$@"; exit
